        if len(ids1) != len(ids2):
            return -1 if len(ids1) < len(ids2) else 1

        return 0

    def sort_key(v):
        major, minor, patch, prerelease_ids = parse_version(v)

        # For sorting: we need a comparable key
        # Create a tuple that sorts correctly
        if prerelease_ids is None:
            # No pre-release: sorts after same version with pre-release
            # Use (major, minor, patch, 1) so it sorts after (major, minor, patch, 0, ...)
            return (major, minor, patch, 1)
        else:
            # Has pre-release: sorts before same version without pre-release
